WITH flattened AS (SELECT id, created_at, coupon_codes, attr_key, attr_value FROM carts LATERAL VIEW EXPLODE(attributes) li AS attr_key, attr_value) SELECT attr_key, DATE_TRUNC('DAY', created_at) AS activity_day, COUNT(*) AS cnt, COUNT(CASE WHEN attr_key = 'utm_source' THEN 1 END) AS utm_source_count, SORT_ARRAY(COLLECT_SET(attr_key)) AS attr_key_list, DENSE_RANK() OVER (PARTITION BY attr_key ORDER BY COUNT(CASE WHEN attr_key = 'utm_source' THEN 1 END) DESC) AS utm_source_count_dense_rank FROM flattened GROUP BY attr_key, DATE_TRUNC('DAY', created_at)
